        discount: "HOT"
    }
];

let cartCount = 0;

function createProductCard(product, isDeal = false) {
    const card = document.createElement('div');
    card.className = 'product-card';

    let badgeHtml = '';
    if (isDeal && product.discount) {
        badgeHtml = `<span class="badge">${product.discount}</span>`;
    }

    let priceHtml = `<p class="product-price">$${product.price}</p>`;
    if (isDeal && product.oldPrice) {
        priceHtml = `
            <p class="product-price">
                <span class="current-price">$${product.price}</span>
                <span class="old-price" style="text-decoration: line-through; color: #999; font-size: 0.9rem; margin-left: 0.5rem;">$${product.oldPrice}</span>
            </p>
        `;
    }

    card.innerHTML = `
        ${badgeHtml}
        <div class="product-image">
            <img src="${product.image}" alt="${product.name}" loading="lazy">
        </div>
        <div class="product-info">
            <h3>${product.name}</h3>
            ${priceHtml}
            <button class="btn-add-cart" data-id="${product.id}">Add to Cart</button>
        </div>
    `;

    const addButton = card.querySelector('.btn-add-cart');
    addButton.addEventListener('click', () => {
        addToCart();
    });

    return card;
}

function addToCart() {
    cartCount++;
    const countElement = document.querySelector('.cart-count');
    countElement.textContent = cartCount;

    // Simple visual feedback
    const cartBtn = document.getElementById('cart-btn');
    cartBtn.style.transform = 'scale(1.2)';
    setTimeout(() => {
        cartBtn.style.transform = 'scale(1)';
    }, 200);
}

function init() {
    const featuredGrid = document.getElementById('featured-grid');
    const dealsGrid = document.getElementById('deals-grid');

    PRODUCTS.forEach(product => {
        featuredGrid.appendChild(createProductCard(product));
    });

    DEALS.forEach(deal => {
        dealsGrid.appendChild(createProductCard(deal, true));
    });

    // Newsletter form handling
    const newsletterForm = document.querySelector('.newsletter-form');
    newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const email = document.getElementById('email-input').value;
        alert(`Thank you for subscribing, ${email}!`);
        newsletterForm.reset();
    });
}

document.addEventListener('DOMContentLoaded', init);
