    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.product-price {
    font-weight: 700;
}

.badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background: var(--primary-color);
    color: var(--secondary-color);
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
    font-weight: 600;
}

.btn-add-cart {
    width: 100%;
    margin-top: 1rem;
    padding: 0.75rem;
    background: var(--primary-color);
    color: var(--secondary-color);
    border: none;
    cursor: pointer;
    font-weight: 600;
    transition: var(--transition);
}

.btn-add-cart:hover {
    background: var(--accent-color);
}

/* Editorial */
.editorial-card {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
    margin: 6rem 0;
}

.editorial-content h2 {
    font-size: 3rem;
    margin-bottom: 1.5rem;
    letter-spacing: -1.5px;
}

.editorial-content p {
    font-size: 1.1rem;
    color: var(--text-muted);
    margin-bottom: 2rem;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 1rem 2.5rem;
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
    border: 1px solid var(--primary-color);
    cursor: pointer;
}

.btn-primary {
    background: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background: var(--accent-color);
    border-color: var(--accent-color);
}

.btn-secondary {
    background: transparent;
    color: var(--primary-color);
}

.btn-secondary:hover {
    background: var(--primary-color);
    color: var(--secondary-color);
}

/* Footer */
.site-footer {
    background: var(--primary-color);
    color: var(--secondary-color);
    padding: 4rem 0 2rem;
    margin-top: 6rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    color: var(--secondary-color);
    margin-bottom: 1rem;
    display: block;
}

.footer-links h3, .footer-newsletter h3 {
    margin-bottom: 1.5rem;
    font-size: 1.2rem;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 0.75rem;
}

.footer-links a {
    color: #999;
    text-decoration: none;
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--secondary-color);
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.75rem;
    border: none;
    background: #222;
    color: var(--secondary-color);
}

.footer-bottom {
    border-top: 1px solid #222;
    padding-top: 2rem;
    text-align: center;
    font-size: 0.9rem;
    color: #666;
}

/* Responsive */
@media (max-width: 992px) {
    .hero, .editorial-card {
        grid-template-columns: 1fr;
    }
    .hero-content {
        order: 2;
        padding: 2rem;
    }
    .hero-content h1 {
        font-size: 3rem;
    }
    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 600px) {
    .nav-links {
        display: none;
    }
    .footer-grid {
        grid-template-columns: 1fr;
    }
}
