     line-height: 1.6;
     color: var(--text-color);
     background-color: var(--bg-color);
 }

 img {
     max-width: 100%;
     display: block;
 }

 .container {
     max-width: var(--container-width);
     margin: 0 auto;
     padding: 0 2rem;
 }

 .sr-only {
     position: absolute;
     width: 1px;
     height: 1px;
     padding: 0;
     margin: -1px;
     overflow: hidden;
     clip: rect(0, 0, 0, 0);
     border: 0;
 }

 /* Header */
 .site-header {
     background: var(--secondary-color);
     border-bottom: 1px solid var(--border-color);
     position: sticky;
     top: 0;
     z-index: 100;
 }

 .main-nav {
     display: flex;
     justify-content: space-between;
     align-items: center;
     height: 80px;
 }

 .logo {
     font-size: 1.5rem;
     font-weight: 800;
     text-decoration: none;
     color: var(--primary-color);
     letter-spacing: -0.5px;
 }

 .nav-links {
     display: flex;
     list-style: none;
     gap: 2rem;
 }

 .nav-links a {
     text-decoration: none;
     color: var(--text-color);
     font-weight: 500;
     transition: var(--transition);
 }

 .nav-links a:hover, .nav-links a:focus {
     color: var(--text-muted);
     outline: none;
 }

 .nav-links a:focus-visible {
     outline: 2px solid var(--primary-color);
     outline-offset: 4px;
 }

 .icon-btn:focus-visible {
     outline: 2px solid var(--primary-color);
     outline-offset: 2px;
 }

 .btn:focus-visible {
     outline: 3px solid var(--primary-color);
     outline-offset: 4px;
 }

 .nav-utils {
     display: flex;
     gap: 1rem;
     align-items: center;
 }

 .icon-btn {
     background: none;
     border: none;
     cursor: pointer;
     position: relative;
     padding: 0.5rem;
 }

 .cart-count {
     position: absolute;
     top: 0;
     right: 0;
     background: var(--primary-color);
     color: var(--secondary-color);
     font-size: 0.7rem;
     width: 18px;
     height: 18px;
     border-radius: 50%;
     display: flex;
     align-items: center;
     justify-content: center;
 }

 /* Hero */
 .hero {
     display: grid;
     grid-template-columns: 1fr 1fr;
     align-items: center;
     background: var(--secondary-color);
     overflow: hidden;
 }

 .hero-content {
     padding: 4rem;
 }

 .hero-content h1 {
     font-size: 4rem;
     line-height: 1.1;
     margin-bottom: 1.5rem;
     letter-spacing: -2px;
 }

 .hero-content p {
     font-size: 1.25rem;
     color: var(--text-muted);
     margin-bottom: 2rem;
     max-width: 480px;
 }

 .hero-image {
     height: 100%;
 }

 .hero-image img {
     width: 100%;
     height: 100%;
     object-fit: cover;
 }

 /* Sections */
 .section-header {
     display: flex;
     justify-content: space-between;
     align-items: flex-end;
     margin: 4rem 0 2rem;
 }

 .section-header h2 {
     font-size: 2rem;
     letter-spacing: -1px;
 }

 .view-all {
     color: var(--text-muted);
     text-decoration: none;
     font-weight: 500;
     border-bottom: 1px solid currentColor;
 }

 /* Product Grid */
 .product-grid {
     display: grid;
     grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
     gap: 2rem;
 }

 .product-card {
     background: var(--secondary-color);
     border: 1px solid var(--border-color);
     padding: 1rem;
     transition: var(--transition);
     position: relative;
 }

 .product-card:hover, .product-card:focus-within {
     transform: translateY(-4px);
     box-shadow: 0 10px 20px rgba(0,0,0,0.05);
 }

 .product-image {
     aspect-ratio: 3/4;
     overflow: hidden;
     margin-bottom: 1rem;
 }

 .product-image img {
     width: 100%;
     height: 100%;
     object-fit: cover;
     transition: var(--transition);
 }

 .product-card:hover .product-image img {
     transform: scale(1.05);
 }

 .product-info h3 {
     font-size: 1.1rem;
     margin-bottom: 0.5rem;
 }

 .product-price {
     font-weight: 700;
 }

 .badge {
     position: absolute;
     top: 1rem;
     left: 1rem;
     background: var(--primary-color);
     color: var(--secondary-color);
     padding: 0.25rem 0.75rem;
     font-size: 0.8rem;
     font-weight: 600;
 }

 .btn-add-cart {
     width: 100%;
     margin-top: 1rem;
     padding: 0.75rem;
     background: var(--primary-color);
     color: var(--secondary-color);
     border: none;
     cursor: pointer;
     font-weight: 600;
     transition: var(--transition);
 }

 .btn-add-cart:hover:not(:disabled) {
     background: var(--accent-color);
 }

 .btn-add-cart:disabled {
     background: #444;
     cursor: not-allowed;
 }

 /* Editorial */
 .editorial-card {
     display: grid;
     grid-template-columns: 1fr 1fr;
     gap: 4rem;
     align-items: center;
     margin: 6rem 0;
 }

 .editorial-content h2 {
     font-size: 3rem;
     margin-bottom: 1.5rem;
     letter-spacing: -1.5px;
 }

 .editorial-content p {
     font-size: 1.1rem;
     color: var(--text-muted);
     margin-bottom: 2rem;
 }

 /* Buttons */
 .btn {
     display: inline-block;
     padding: 1rem 2.5rem;
     text-decoration: none;
     font-weight: 600;
     transition: var(--transition);
     border: 1px solid var(--primary-color);
     cursor: pointer;
 }

 .btn-primary {
     background: var(--primary-color);
     color: var(--secondary-color);
 }

 .btn-primary:hover {
     background: var(--accent-color);
     border-color: var(--accent-color);
 }

 .btn-secondary {
     background: transparent;
     color: var(--primary-color);
 }

 .btn-secondary:hover {
     background: var(--primary-color);
     color: var(--secondary-color);
 }

 /* Footer */
 .site-footer {
     background: var(--primary-color);
     color: var(--secondary-color);
     padding: 4rem 0 2rem;
     margin-top: 6rem;
 }

 .footer-grid {
     display: grid;
     grid-template-columns: 2fr 1fr 1fr 2fr;
     gap: 4rem;
     margin-bottom: 4rem;
 }

 .footer-brand .logo {
     color: var(--secondary-color);
     margin-bottom: 1rem;
     display: block;
 }

 .footer-links h3, .footer-newsletter h3 {
     margin-bottom: 1.5rem;
     font-size: 1.2rem;
 }

 .footer-links ul {
     list-style: none;
 }

 .footer-links li {
     margin-bottom: 0.75rem;
 }

 .footer-links a {
     color: #999;
     text-decoration: none;
     transition: var(--transition);
 }

 .footer-links a:hover {
     color: var(--secondary-color);
 }

 .newsletter-form {
     display: flex;
     gap: 0.5rem;
     margin-top: 1rem;
 }

 .newsletter-form input {
     flex: 1;
     padding: 0.75rem;
     border: none;
     background: #222;
     color: var(--secondary-color);
 }

 .footer-bottom {
     border-top: 1px solid #222;
     padding-top: 2rem;
     text-align: center;
     font-size: 0.9rem;
     color: #666;
 }

 /* Responsive */
 @media (max-width: 992px) {
     .hero, .editorial-card {
         grid-template-columns: 1fr;
     }
     .hero-content {
         order: 2;
         padding: 2rem;
     }
     .hero-content h1 {
         font-size: 3rem;
     }
     .footer-grid {
         grid-template-columns: 1fr 1fr;
     }
 }

 @media (max-width: 600px) {
     .nav-links {
         display: none;
     }
     .footer-grid {
         grid-template-columns: 1fr;
     }
 }

